n range(v)]\n\ndef program(p, m, v=1, policy=\"1f1b\", max_pending_backward=None, warm=None):\n    P = p * v\n    prog = [[] for _ in range(p)]\n    for s in range(p):\n        units = _units_of(s, p, v)\n        if policy == \"afab\":\n            seq = [(\"F\", i, u) for i in range(m) for u in units]\n            seq += [(\"B\", i, u) for i in range(m) for u in reversed(units)]\n            seq += [(\"W\", i, u) for i in range(m) for u in units]\n            prog[s] = seq; continue\n        if warm is not None:\n            wu = {u: max(0, min(m, warm(u))) for u in units}\n        elif policy == \"zb2p\":\n            cap = (2 * p) if max_pending_backward is None else max_pending_backward\n            wu = {u: max(0, min(m, cap // v, ceil((P - 1 - u) / p))) for u in units}\n        else:                                    # canonical 1f1b / interleaved-1f1b\n            wu = {u: max(0, min(m, ceil((P - 1 - u) / p))) for u in units}\n        pend = {u: list(range(wu[u])) for u in units}      # microbatches fwd'd, awaiting B\n        nxt  = {u: wu[u] for u in units}                   # next microbatch to forward\n        seq = []\n        Wmax = max(wu.values(), default=0)\n        for k in range(Wmax):                              # warmup phase\n            for u in units:\n                if k < wu[u]: seq.append((\"F\", k, u))\n        while any(nxt[u] < m for u in units):              # steady state: 1F then 1B\n            for u in units:\n                if nxt[u] < m:\n                    seq.append((\"F\", nxt[u], u)); nxt[u] += 1\n            for u in reversed(units):\n                if pend[u]:\n                    i = pend[u].pop(0); seq.append((\"B\", i, u)); seq.append((\"W\", i, u))\n        for u in reversed(units):                          # cooldown\n            while pend[u]:\n                i = pend[u].pop(0); seq.append((\"B\", i, u)); seq.append((\"W\", i, u))\n        if policy == \"zb2p\":                               # deferred weight grads\n            seq = [t for t in seq if t[0] != \"W\"]\n            pend2 = {u: list(range(m)) for u in units}\n            done = {t for t in seq}\n            for u in units:\n                for i in range(m):\n                    if (\"B\", i, u) in done: seq.append((\"W\", i, u))\n        prog[s] = seq\n    return prog\n\ndef simulate(p, m, f, b, w=0.0, v=1, policy=\"1f1b\", imbalance=None, comm=0.0,\n             max_pending_backward=None, warm=None):\n    P = p * v\n    dur = {\"F\": f / v, \"B\": b / v, \"W\": w / v}\n    imb = (lambda u: 1.0) if imbalance is None else imbalance\n    prog = program(p, m, v, policy, max_pending_backward, warm)\n    task, start = {}, {}\n    for s, seq in enumerate(prog):\n        for t in set(seq):\n            task[t] = (s, dur[t[0]] * imb(t[2])); start[t] = 0.0\n    succ = {t: [] for t in task}; indeg = {t: 0 for t in task}\n    def add(a, c):\n        succ[a].append(c); indeg[c] += 1\n    for seq in prog:\n        for a, c in zip(seq, seq[1:]):\n            if a != c: add(a, c)\n    for (k, i, u) in list(task):\n        if k == \"F\" and u > 0: add((\"F\", i, u - 1), (k, i, u))\n        if k == \"B\":\n            add((\"F\", i, u), (k, i, u))\n            if u < P - 1: add((\"B\", i, u + 1), (k, i, u))\n        if k == \"W\": add((\"B\", i, u), (k, i, u))\n    q = deque(t for t in task if indeg[t] == 0); topo = []\n    while q:\n        t = q.popleft(); topo.append(t)\n        for c in succ[t]:\n            indeg[c] -= 1\n            if indeg[c] == 0: q.append(c)\n    assert len(topo) == len(task), \"cycle in schedule DAG\"\n    E = lambda t: start[t] + task[t][1]\n    for t in topo:\n        for nx in succ[t]:\n            if E(t) > start[nx]: start[nx] = E(t)\n    T = max(E(t) for t in task)\n    bydev = {s: [] for s in range(p)}\n    for t, (s, d) in task.items(): bydev[s].append((start[t], E(t)))\n    rows = []\n    for s in range(p):\n        tl = sorted(bydev[s]); busy = sum(e - a for a, e in tl)\n        intra = sum(tl[j + 1][0] - tl[j][1] for j in range(len(tl) - 1))\n        rows.append(dict(stage=s, busy=busy, idle=T - busy, bubble=(T - busy) / T,\n                         pre=tl[0][0], intra=intra, post=T - tl[-1][1]))\n    agg = 1 - sum(r[\"busy\"] for r in rows) / (p * T)\n    return dict(T=T, agg=agg, per_stage=rows,\n                work_per_dev=m * (f + b + w), speedup=m * (f + b + w) / (p * T))\n\ndef peak_activation_slots(p, m, v=1, policy=\"1f1b\", max_pending_backward=None):\n    peak = 0\n    for seq in program(p, m, v, policy, max_pending_backward):\n        held = hi = 0\n        for k, i, u in seq:\n            if k == \"F\": held += 1; hi = max(hi, held)\n            elif k == \"B\": held -= 1\n        peak = max(peak, hi)\n    return peak\nPY\ncd /workspace/design && timeout 200 python3 - <<'PY'\nimport time\nfrom sched_sim import simulate, peak_activation_slots\nprint(\"== G1: w=0,b=f=1,comm=0 -> textbook (p-1)/(m+p-1) ==\")\nbad=[]\nfor p in (2,4,8,16):\n    for m in (p,2*p,4*p,8*p,16*p):\n        ana=(p-1)/(m+p-1)\n        for pol in (\"afab\",\"1f1b\"):\n            r=simulate(p,m,1,1,0,policy=pol)\n            if abs(r['agg']-ana)>1e-12: bad.append((p,m,pol,round(r['agg'],6),round(ana,6)))\nprint(\"  AFAB/1F1B mismatches:\", bad or \"NONE (exact, 40 cases)\")\nfor (p,v,m) in ((4,2,16),(8,2,32),(8,4,64),(16,4,64)):\n    r=simulate(p,m,1,1,0,v=v,policy=\"1f1b\"); a=(p-1)/(v*m+p-1)\n    print(f\"  interleaved p={p} v={v} m={m}: sim={r['agg']:.6f} ana={a:.6f} {'OK' if abs(r['agg']-a)<1e-12 else 'DELTA %.2e'%abs(r['agg']-a)}\")\nprint(\"== b/f ratio matters (textbook N/A) ==\")\nfor (f,b) in ((1,1),(1,2),(1,3)):\n    r=simulate(8,64,f,b,0.5); print(f\"  f={f} b={b} w=0.5: T={r['T']:.2f} agg={r['agg']:.4f}\")\nprint(\"== imbalance 1.25x on middle stage (p=8,m=64,f=1,b=2,w=1) ==\")\nr0=simulate(8,64,1,2,1); r1=simulate(8,64,1,2,1,imbalance=lambda u:1.25 if u==4 else 1.0)\nprint(f\"  balanced agg={r0['agg']:.4f} T={r0['T']:.1f} | imbalanced agg={r1['agg']:.4f